  int a=u[i], b=v[i];
  to[ec]=b; nx[ec]=head[a]; head[a]=ec++;
  to[ec]=a; nx[ec]=head[b]; head[b]=ec++;
}
for(int i=0;i<n;i++) col[i]=-1;
