int qh=0,qt=0;
col[0]=0; q[qt++]=0;
while(qh<qt){
  int x=q[qh++];
  for(int e=head[x]; e!=-1; e=nx[e]){
    int y=to[e];
    if(col[y]==-1){ col[y]=col[x]^1; q[qt++]=y; }
  }
}
free(head); free(to); free(nx); free(q);

long long L=0,R=0;
